void main() {
  tearDown(() async {
    await Simulator.reset();
  });

  Future<void> runInterFrame({
    required List<int> obu,
    required int tileStart,
    required int tileEnd,
    required String cdfHex,
    required String nsymsHex,
    required int allowHpV,
    required int forceIntV,
    required int txModeSelV,
    required int mmSwitchV,
    required int allowWarpV,
    required List<int> goldenRng,
    required List<List<int>> goldenResid,
    required List<List<int>> goldenBlocks,
    required int expSyms,
    required int expRng,
    required bool expectResidual,
    int maxBytes = 64,
    List<int> txCoeffSizes = const [0, 1, 2],
  }) async {
    final buf = Uint8List.fromList(obu);

    const ms = HarborInterFrameWalk.maxSyms;
    const nctx = HarborInterFrameWalk.numCtx;
    final cdfInVal = BigInt.parse(cdfHex, radix: 16);
    final nsymsInVal = BigInt.parse(nsymsHex, radix: 16);

    final window = Uint8List(maxBytes);
    for (var i = 0; tileStart + i < tileEnd && i < maxBytes; i++) {
      window[i] = buf[tileStart + i];
    }

    BigInt packBytes(List<int> b) {
      var v = BigInt.zero;
      for (var i = 0; i < b.length; i++) {
        v |= BigInt.from(b[i] & 0xFF) << (i * 8);
      }
      return v;
    }

    final t = HarborInterFrameWalk(
      maxBytes: maxBytes,
      txCoeffSizes: txCoeffSizes,
    );
    final clk = SimpleClockGenerator(10).clk;
    final reset = Logic(name: 'reset');
    final start = Logic(name: 'start');
    final bytes = Logic(name: 'bytes', width: maxBytes * 8);
    final allowHp = Logic(name: 'allow_hp');
    final forceInt = Logic(name: 'force_int');
    final txModeSel = Logic(name: 'tx_mode_select');
    final skipModePresent = Logic(name: 'skip_mode_present');
    final refModeSelect = Logic(name: 'ref_mode_select');
    final skipRef0 = Logic(name: 'skip_ref0', width: 3);
    final skipRef1 = Logic(name: 'skip_ref1', width: 3);
    final signBias = Logic(name: 'sign_bias', width: 8);
    final maskedEn = Logic(name: 'enable_masked_compound');
    final mmSwitch = Logic(name: 'mm_switchable');
    final allowWarp = Logic(name: 'allow_warped_motion');
    final cdfIn = Logic(name: 'cdf_in', width: nctx * ms * 16);
    final nsymsIn = Logic(name: 'nsyms_in', width: nctx * 5);

    void conn(String p, Logic s) => t.input(p).srcConnection! <= s;
    conn('clk', clk);
    conn('reset', reset);
    conn('start', start);
    conn('bytes', bytes);
    conn('allow_hp', allowHp);
    conn('force_integer_mv', forceInt);
    conn('tx_mode_select', txModeSel);
    conn('skip_mode_present', skipModePresent);
    conn('ref_mode_select', refModeSelect);
    conn('skip_ref0', skipRef0);
    conn('skip_ref1', skipRef1);
    conn('sign_bias', signBias);
    conn('enable_masked_compound', maskedEn);
    conn('mm_switchable', mmSwitch);
    conn('allow_warped_motion', allowWarp);
    final enableII = Logic(name: 'enable_interintra');
    conn('enable_interintra', enableII);
    conn('cdf_in', cdfIn);
    conn('nsyms_in', nsymsIn);
    await t.build();

    reset.inject(1);
    start.inject(0);
    bytes.inject(packBytes(window));
    allowHp.inject(allowHpV);
    forceInt.inject(forceIntV);
    txModeSel.inject(txModeSelV);
    // These single-ref frames are REFERENCE_MODE SINGLE with skip_mode absent.
    skipModePresent.inject(0);
    refModeSelect.inject(0);
    skipRef0.inject(1);
    skipRef1.inject(7);
    signBias.inject(0);
    maskedEn.inject(1);
    mmSwitch.inject(mmSwitchV);
    allowWarp.inject(allowWarpV);
    enableII.inject(0);
    cdfIn.inject(cdfInVal);
    nsymsIn.inject(nsymsInVal);

    Simulator.setMaxSimTime(200000000);
    unawaited(Simulator.run());
    await clk.nextPosedge;
    reset.inject(0);
    await clk.nextPosedge;
    start.inject(1);
    await clk.nextPosedge;
    start.inject(0);

    int sgn16(int v) => v >= 0x8000 ? v - 0x10000 : v;

    // Sample rng on every sym_valid pulse, capture per-block outputs on
    // block_valid.
    final hwRng = <int>[];
    final hwBlocks = <List<int>>[];
    final hwResid = <List<int>>[]; // [eob, txType]
    var guard = 0;
    while (true) {
      final doneV = t.output('done').value;
      if (doneV.isValid && doneV.toInt() == 1) break;
      if (!doneV.isValid) {
        // ignore: avoid_print
        print('done went X at guard=$guard after ${hwRng.length} symbols');
        break;
      }
      await clk.nextPosedge;
      final sv = t.output('sym_valid').value;
      if (sv.isValid && sv.toInt() == 1) {
        final rv = t.output('rng').value;
        hwRng.add(rv.isValid ? rv.toInt() : -1);
      }
      final bv = t.output('block_valid').value;
      if (bv.isValid && bv.toInt() == 1) {
        hwBlocks.add([
          t.output('blk_r').value.toInt(),
          t.output('blk_c').value.toInt(),
          t.output('blk_bs').value.toInt(),
          t.output('blk_mode').value.toInt(),
          t.output('blk_ref0').value.toInt(),
          sgn16(t.output('blk_mvrow').value.toInt()),
          sgn16(t.output('blk_mvcol').value.toInt()),
          t.output('blk_modectx').value.toInt(),
          t.output('blk_count').value.toInt(),
        ]);
      }
      final rvld = t.output('res_valid').value;
      if (rvld.isValid && rvld.toInt() == 1) {
        hwResid.add([
          t.output('res_eob').value.toInt(),
          t.output('res_txtype').value.toInt(),
        ]);
      }
      if (++guard > 200000) fail('inter frame decode timeout');
    }

    // Compare per-symbol rng against the SW reference (rngAfter per symbol).
    var firstDiff = -1;
    final nCmp = hwRng.length < goldenRng.length
        ? hwRng.length
        : goldenRng.length;
    for (var i = 0; i < nCmp; i++) {
      if (hwRng[i] != goldenRng[i]) {
        firstDiff = i;
        break;
      }
    }
    if (firstDiff >= 0) {
      // ignore: avoid_print
      print(
        'FIRST DIVERGENCE at symbol $firstDiff: '
        'HW rng=${hwRng[firstDiff]} SW rngAfter=${goldenRng[firstDiff]}',
      );
    }
    // ignore: avoid_print
    print(
      'HW decoded ${hwRng.length} symbols; SW ${goldenRng.length}. '
      'In-sync through symbol '
      '${firstDiff < 0 ? nCmp - 1 : firstDiff - 1}.',
    );

    // Full-frame bit-exact sync gate.
    expect(firstDiff, equals(-1), reason: 'every od_ec symbol matches SW');
    expect(
      hwRng.length,
      equals(expSyms),
      reason: 'HW decodes all $expSyms symbols',
    );
    expect(
      hwRng.last,
      equals(expRng),
      reason: 'frame-end od_ec rng == $expRng',
    );

    // Residual gate: every non-zero luma txb's eob/tx_type bit-exact vs the SW
    // reference in decode order (the per-symbol rng sync above proves the
    // coefficients).
    if (expectResidual) {
      expect(
        hwResid.length,
        equals(goldenResid.length),
        reason: 'HW decodes all ${goldenResid.length} residual luma txbs',
      );
      for (var i = 0; i < goldenResid.length && i < hwResid.length; i++) {
        expect(
          hwResid[i],
          equals(goldenResid[i]),
          reason: 'residual luma txb $i [eob, txType]',
        );
      }
    } else {
      expect(hwResid, isEmpty, reason: 'all-skip frame has no residual');
    }

    // Leaf-level: every block's partition/mode/ref/MV/mode_context matches the
    // SW reference.
    final sw0 = goldenBlocks;
    expect(
      hwBlocks.length,
      equals(sw0.length),
      reason: 'HW decodes all ${sw0.length} inter blocks',
    );
    for (var i = 0; i < sw0.length; i++) {
      final g = sw0[i];
      final b = hwBlocks[i];
      expect(
        [b[0], b[1], b[2]],
        equals([g[0], g[1], g[2]]),
        reason: 'block $i position/size',
      );
      expect(b[3], equals(g[5]), reason: 'block $i inter_mode');
      expect(b[4], equals(g[4]), reason: 'block $i ref0');
      expect([b[5], b[6]], equals([g[7], g[8]]), reason: 'block $i MV');
      expect(b[7], equals(g[9]), reason: 'block $i mode_context');
      expect(b[8], equals(g[10]), reason: 'block $i refMvCount');
    }

    await Simulator.endSimulation();
  }

  test(
    'HarborInterFrameWalk: real single-ref SKIP-only inter frame sync vs SW',
    () async {
      await runInterFrame(
        obu: _obu,
        tileStart: 481,
        tileEnd: 512,
        cdfHex: _cdfHexObu,
        nsymsHex: _nsymsHexObu,
        allowHpV: 0,
        forceIntV: 0,
        txModeSelV: 0,
        mmSwitchV: 0,
        allowWarpV: 0,
        goldenRng: _rngObu,
        goldenResid: _residObu,
        goldenBlocks: _blocksObu,
        expSyms: 238,
        expRng: 60688,
        expectResidual: false,
      );
    },
  );

  test(
    'HarborInterFrameWalk: single-ref inter frame with RESIDUAL sync vs SW',
    () async {
      // cq32 4-quadrant frame: 21 blocks, one non-skip BLOCK_16X16 carrying a
      // TX_16X16 (V_DCT, eob=4) luma residual + all-zero chroma. Full frame-end
      // od_ec sync (310 symbols, rng == 56080) proves the residual coefficients.
      await runInterFrame(
        obu: _obuResid,
        tileStart: 636,
        tileEnd: 677,
        cdfHex: _cdfHexResid,
        nsymsHex: _nsymsHexResid,
        allowHpV: 1,
        forceIntV: 0,
        txModeSelV: 0,
        mmSwitchV: 0,
        allowWarpV: 0,
        goldenRng: _rngResid,
        goldenResid: _residResid,
        goldenBlocks: _blocksResid,
        expSyms: 310,
        expRng: 56080,
        expectResidual: true,
      );
    },
  );

  test(
    'HarborInterFrameWalk: single-ref inter frame with VAR-TX residual sync',
    () async {
      // cq16 4-quadrant frame: txMode SELECT, two BLOCK_8X8 non-skip var-tx blocks
      // (one splits into 4 TX_4X4, one stays TX_8X8) exercising the txfm_partition
